parameters.jsCode:
// Extraer datos del mensaje de Instagram
const body = $input.item.json.body;

// Soporte para DM (messaging) y comentarios
const entry = body?.entry?.[0];
const messaging = entry?.messaging?.[0];
const change = entry?.changes?.[0];

let senderId = '';
let messageText = '';
let messageType = '';
let commentId = '';

if (messaging) {
  // DM directo
  senderId = messaging.sender?.id || '';
  messageText = messaging.message?.text || '';
  messageType = 'dm';
} else if (change?.field === 'comments') {
  // Comentario en post
  senderId = change.value?.from?.id || '';
  messageText = change.value?.text || '';
  commentId = change.value?.id || '';
  messageType = 'comment';
}

// Detectar intención
const text = messageText.toLowerCase();
const esPrecio = /precio|cuanto|cuesta|vale|costo/.test(text);
const esCompra = /comprar|quiero|pedir|llevar|pedido/.test(text);
const esEnvio = /envio|enví|llega|demora|días|cuanto tarda/.test(text);
const esSaludo = /hola|buenas|buenos|buen dia|hi|info/.test(text);
const esTermo = /termo|vaso|térm|sensor|temperatura/.test(text);
const esParlante = /parlante|bluetooth|clip|música/.test(text);

let intent = 'otro';
if (esPrecio) intent = 'precio';
else if (esCompra) intent = 'compra';
else if (esEnvio) intent = 'envio';
else if (esTermo) intent = 'producto_termo';
else if (esParlante) intent = 'producto_parlante';
else if (esSaludo) intent = 'saludo';

return {
  senderId,
  messageText,
  messageType,
  commentId,
  intent,
  rawBody: body
};

